create or replace function public.home_active_events(p_limit integer default 3) returns table(id uuid,title text,description text,event_date date,event_time time,location_id uuid) language sql security definer set search_path=public as $$ select e.id,e.title,e.description,e.event_date,e.event_time,e.location_id from public.business_events e where e.status in ('scheduled','active') and e.event_date >= current_date order by e.event_date asc,e.event_time asc nulls last limit greatest(1,least(coalesce(p_limit,3),10)); $$; revoke all on function public.home_active_events(integer) from public; grant execute on function public.home_active_events(integer) to anon,authenticated; create or replace function public.home_active_contests(p_limit integer default 3) returns table(id uuid,name text,description text,starts_at timestamptz,ends_at timestamptz,status text) language sql security definer set search_path=public as $$ select c.id,c.name,c.description,c.starts_at,c.ends_at,c.status from public.contests c where c.status in ('active','scheduled') and (c.ends_at is null or c.ends_at > now()) order by coalesce(c.starts_at,c.created_at) asc limit greatest(1,least(coalesce(p_limit,3),10)); $$; revoke all on function public.home_active_contests(integer) from public; grant execute on function public.home_active_contests(integer) to anon,authenticated;
